params.query:
SELECT DISTINCT ?item ?coord ?kind WHERE {
  SERVICE wikibase:box { ?item wdt:P625 ?coord .
    bd:serviceParam wikibase:cornerWest "Point(71.2179735 50.8576076)"^^geo:wktLiteral .
    bd:serviceParam wikibase:cornerEast "Point(71.7851913 51.3511101)"^^geo:wktLiteral . }
  VALUES ?kind { wd:Q33506 wd:Q1007870 wd:Q24354 wd:Q41253 wd:Q22698 wd:Q4989906 wd:Q570116 wd:Q9259 wd:Q16970 wd:Q12280 wd:Q483110 wd:Q7075 wd:Q11315 wd:Q182832 wd:Q41176 }
  ?item wdt:P31/wdt:P279* ?kind .
} ORDER BY ?item ?kind ?coord LIMIT 250 OFFSET 0
